<?php
namespace App\Actions;
use App\Models\TreasuryItem;use App\Models\TreasuryItemTransaction;use App\Models\TreasuryTransaction;use App\Services\AuditService;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class SellTreasuryItem
{
 public function __construct(private readonly AuditService $audit){}
 public function execute(TreasuryItem $item,int $quantity,int $totalAmount,string $comment,int $userId):TreasuryItem{return DB::transaction(function()use($item,$quantity,$totalAmount,$comment,$userId){$locked=TreasuryItem::query()->lockForUpdate()->findOrFail($item->id);if($quantity>$locked->available_quantity)throw ValidationException::withMessages(['quantity'=>__('domain.treasury.insufficient_quantity', ['available'=>$locked->available_quantity])]);$oldQuantity=$locked->quantity;$locked->decrement('quantity',$quantity);TreasuryItemTransaction::query()->create(['treasury_item_id'=>$locked->id,'type'=>'manual_sale','quantity_delta'=>-$quantity,'reason'=>$comment,'created_by'=>$userId]);DB::select('SELECT pg_advisory_xact_lock(?)',[834721]);$balance=(int)(TreasuryTransaction::query()->latest('id')->value('balance_after')??0);TreasuryTransaction::query()->create(['type'=>'manual_income','amount'=>$totalAmount,'balance_after'=>$balance+$totalAmount,'description'=>'Продажа '.$locked->item_name.': '.$comment,'related_entity_type'=>TreasuryItem::class,'related_entity_id'=>$locked->id,'created_by'=>$userId]);$this->audit->record('treasury_item.sold',$locked,['quantity'=>$oldQuantity],['quantity'=>$locked->quantity,'sold_quantity'=>$quantity,'total_amount'=>$totalAmount,'comment'=>$comment]);return $locked->refresh();});}
}
